contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, uint am) public payable {
        require(address(this).balance >= amount);
        // Seed the caller's account with `amount` wei so a withdrawal is possible.
        c.Put{value: amount}(0);
        uint cbalBefore = address(c).balance;
        (, uint myBalBefore) = c.Acc(address(this));
        // The deciding call: attempt to withdraw `am` under arbitrary conditions.
        c.Collect(am);
        uint cbalAfter = address(c).balance;
        (, uint myBalAfter) = c.Acc(address(this));
        // Conservation: whatever left the contract's balance left the caller's
        // ledger by the same amount (Collect only moves Ether it debits, and
        // a blocked Collect moves nothing). No underflow: the contract always
        // holds at least the sum of recorded balances.
        assert(cbalBefore - cbalAfter == myBalBefore - myBalAfter);
    }
    receive() external payable {}
}

